    planAvailability: { status: 'unknown', note: 'The plan is not confirmed in the test fixture.' },
    sources: [], exampleQuestions: [],
    demonstration: { level: 'demonstrable', evidence: 'test', cloneSurfaces: [], tools: [] },
    ...partial,
  };
}

